import React, { useEffect, useState } from "react";
import axios from "../utils/axios";
import { Spinner, Card, Button, Container, Row, Col, Alert } from "react-bootstrap";

const UpcomingEvents = () => {
  const [events, setEvents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [message, setMessage] = useState("");

  useEffect(() => {
    const fetchEvents = async () => {
      try {
        const token = localStorage.getItem("accessToken");
        if (!token) {
          setError("User not authenticated");
          return;
        }

        const response = await axios.get("/api/events/upcoming", {
          headers: { Authorization: `Bearer ${token}` },
        });

        setEvents(response.data);
      } catch (error) {
        setError(error.response?.data?.message || "Failed to fetch events");
      } finally {
        setLoading(false);
      }
    };

    fetchEvents();
  }, []);

  const handleRegister = async (eventId) => {
    try {
      const token = localStorage.getItem("accessToken");
      if (!token) {
        setError("User not authenticated");
        return;
      }

      const response = await axios.post(`/api/events/${eventId}/register`, {}, {
        headers: { Authorization: `Bearer ${token}` },
      });

      setMessage(response.data.message);
      setEvents((prevEvents) =>
        prevEvents.map((event) =>
          event._id === eventId ? { ...event, isRegistered: true } : event
        )
      );
    } catch (error) {
      setError(error.response?.data?.message || "Failed to register");
    }
  };

  const handleUnregister = async (eventId) => {
    try {
      const response = await axios.delete(`/api/events/${eventId}/unregister`);

      setMessage(response.data.message);
      setEvents((prevEvents) =>
        prevEvents.map((event) =>
          event._id === eventId ? { ...event, isRegistered: false } : event
        )
      );
    } catch (error) {
      setError(error.response?.data?.message || "Failed to unregister");
    }
  };

  return (
    <Container>
      <h2>Upcoming Events</h2>
      {loading && <Spinner animation="border" />}
      {error && <Alert variant="danger">{error}</Alert>}
      {message && <Alert variant="success">{message}</Alert>}
      <Row>
        {events.map((event) => (
          <Col key={event._id} md={4}>
            <Card>
              <Card.Body>
                <Card.Title>{event.title}</Card.Title>
                <Card.Text>{event.description}</Card.Text>
                {event.isRegistered ? (
                  <Button variant="danger" onClick={() => handleUnregister(event._id)}>
                    Unregister
                  </Button>
                ) : (
                  <Button variant="primary" onClick={() => handleRegister(event._id)}>
                    Register
                  </Button>
                )}
              </Card.Body>
            </Card>
          </Col>
        ))}
      </Row>
    </Container>
  );
};

export default UpcomingEvents;
